// 0.56.37: 1024 -> 4096. Hebt net_service_tcp_write_max von 996 auf
// ~4068 und senkt die Service-Roundtrips grosser Transfers um ~4x
// (Durchsatz-Befund 0.56.25). MUSS mit kernel/service_ipc.zig
// MAX_MESSAGE_SIZE uebereinstimmen (eine Wahrheit, Konsistenz-Check
// in net/core.zig limits).
pub const log_r4x_service_name = "LOGSVC";
