    dma_unpin_buffer: *const fn (*DmaPinnedBuffer) callconv(.c) i32,
    // 0.69.42 (DriverApi Version 20, append-only): isolierte, absolute
    // Deadlinearbeit fuer Audiorefills mit begrenztem Budget und stabilem
    // Geraete-Serialisierungsschluessel.
    driver_work_submit_request: *const fn (*const DriverWorkRequest, *u32) callconv(.c) i32,
    // 0.69.43 (DriverApi Version 21, append-only): ownergebundene Aktivierung
    // eines kernelresidenten USB-Hostbackends ohne zweiten Ressourcenbesitz.
    activate_usb_host_controller: *const fn ([*:0]const u8, u32) callconv(.c) i32,
    // 0.69.48 (DriverApi Version 22, append-only): one owner-bound,
    // synchronous display blit backend with kernel-owned fallback.
    register_display_blit_backend: *const fn ([*:0]const u8, *const DisplayBlitBackend) callconv(.c) i32,
    unregister_display_blit_backend: *const fn ([*:0]const u8) callconv(.c) i32,
    // 0.69.49 (DriverApi Version 23, append-only): IRQ-safe publication of
    // adapter RX work to the bounded, event-driven Netcore handoff.
    net_schedule_rx: *const fn (i32) callconv(.c) i32,
    // 0.69.50 (DriverApi Version 24, append-only): capability selection is
    // queried after registration; packet metadata always retains a flat,
    // byte-identical software fallback.
    net_backend_query: *const fn (i32, *NetBackendNegotiation) callconv(.c) i32,
    net_receive_packet: *const fn (i32, *const NetPacket) callconv(.c) i32,
    // v25 optional memory extension. Header and earlier function offsets stay fixed.
    gfx_memory_query: ?*const fn (*GfxDriverMemoryApi) callconv(.c) i32 = null,
    // v26 optional native submission/IRQ completion and reset bridge.
    gfx_queue_query: ?*const fn (*GfxDriverQueueApi) callconv(.c) i32 = null,
    gfx_output_query: ?*const fn (*GfxDriverOutputApi) callconv(.c) i32 = null,
    gfx_display_query: ?*const fn (*GfxDriverDisplayApi) callconv(.c) i32 = null,
    resource_query: ?*const fn (*DriverResourceApi) callconv(.c) i32 = null,
    heap_query: ?*const fn (*DriverHeapApi) callconv(.c) i32 = null,
    monotonic_clock: ?*const fn (*MonotonicClockInfo) callconv(.c) i32 = null,
    thread_query: ?*const fn (*DriverThreadApi) callconv(.c) i32 = null,
    semaphore_query: ?*const fn (*DriverSemaphoreApi) callconv(.c) i32 = null,
    // Technical facade outside the generated exports block: v34 range sync.
    dma_sync_range_for_device: ?*const fn (*const DmaMapping, u32, u32) callconv(.c) i32 = null,
    dma_sync_range_for_cpu: ?*const fn (*const DmaMapping, u32, u32) callconv(.c) i32 = null,
    // v36: bounded BSP Work slice under the authenticated lifecycle owner.
    driver_work_submit_owned: ?*const fn (DriverWorkHandler, usize, *u32) callconv(.c) i32 = null,
    // v37: external UART/transport registration; original prefix unchanged.
    serial_query: ?*const fn (*DriverSerialApi) callconv(.c) i32 = null,
    // v39: owner-bound catalog epoch callback; all earlier slots unchanged.
    register_audio_output_epoch: ?*const fn ([*:0]const u8, AudioOutputEpochFn) callconv(.c) i32 = null,
};

