    flags: u64 = 0,
    fallback_addr: u64 = 0,
    segments_addr: u64 = 0,
    completion_handle: u64 = 0,
    fallback_bytes: u32 = 0,
    ownership: u32 = net_buffer_ownership_borrowed_until_return,
    queue_index: u16 = 0,
    segment_count: u16 = 0,
    checksum_start: u16 = 0,
    checksum_offset: u16 = 0,
    vlan_tag: u16 = 0,
    gso_size: u16 = 0,
    reserved: u32 = 0,
};

pub const NetTxComplete = *const fn (u64, i32, u32) callconv(.c) void;

pub const NetTxRequest = extern struct {
    version: u32 = net_packet_version,
    size: u32 = @sizeOf(NetTxRequest),
    packet: NetPacket = .{},
    complete: ?NetTxComplete = null,
};

pub const NetTransmitPacketFn = *const fn (?*anyopaque, *const NetTxRequest) callconv(.c) i32;

pub const NetBackendNegotiation = extern struct {
    version: u32 = net_backend_negotiation_version,
    size: u32 = @sizeOf(NetBackendNegotiation),
    offered: u64 = 0,
    accepted: u64 = 0,
    rejected: u64 = 0,
    rx_queue_count: u16 = 1,
    tx_queue_count: u16 = 1,
    max_rx_segments: u16 = 1,
    max_tx_segments: u16 = 1,
    rx_ownership: u32 = net_buffer_ownership_borrowed_until_return,
    tx_ownership: u32 = net_buffer_ownership_borrowed_until_return,
    interrupt_moderation_us: u32 = 0,
    reserved: u32 = 0,
};

pub const NetBackend = extern struct {
    version: u32 = net_backend_version,
    size: u32 = @sizeOf(NetBackend),
    flags: u32 = net_backend_flag_link_up | net_backend_flag_broadcast | net_backend_flag_trusted,
    mtu: u16 = 1500,
    bus_kind: u8 = net_bus_unknown,
    reserved0: u8 = 0,
    bus: u8 = 0,
    device: u8 = 0,
    function: u8 = 0,
    reserved1: u8 = 0,
    vendor_id: u16 = 0,
    device_id: u16 = 0,
    mac: [6]u8 = .{0} ** 6,
    context: ?*anyopaque = null,
    transmit: ?*const fn (?*anyopaque, [*]const u8, u32) callconv(.c) i32 = null,
    poll: ?*const fn (?*anyopaque) callconv(.c) void = null,
    shutdown: ?*const fn (?*anyopaque) callconv(.c) i32 = null,
    status: ?*const fn (?*anyopaque, *NetBackendStatus) callconv(.c) i32 = null,
    // Complete version 2 descriptor required since Kernel 0.1.304. Required
    // bits reject registration unless selected; optional rejected bits use
    // the canonical flat callbacks. transmit_packet remains optional.
    // The first selected metadata consumer is RX L4 checksum.
    offered_capabilities: u64 = 0,
    required_capabilities: u64 = 0,
    rx_queue_count: u16 = 1,
    tx_queue_count: u16 = 1,
    max_rx_segments: u16 = 1,
    max_tx_segments: u16 = 1,
    rx_ownership: u32 = net_buffer_ownership_borrowed_until_return,
    tx_ownership: u32 = net_buffer_ownership_borrowed_until_return,
    interrupt_moderation_us: u32 = 0,
    reserved2: u32 = 0,
    transmit_packet: ?NetTransmitPacketFn = null,
};

// Separate generation2 technical records; canonical removals/projections are
// generated from Generation2.json without changing any legacy field layout.
const technical2 = @import("technical2_generated.zig");
pub const DriverApi2 = technical2.DriverApi2;
pub const ProtocolApi2 = technical2.ProtocolApi2;
pub const AudioBackend2 = technical2.AudioBackend2;
pub const AudioBackendStatus2 = technical2.AudioBackendStatus2;
pub const AudioBackendRegisterFn2 = technical2.AudioBackendRegisterFn2;
pub const AudioBackendStatusFn2 = technical2.AudioBackendStatusFn2;
pub const AudioCaptureBackend2 = technical2.AudioCaptureBackend2;
pub const AudioCaptureRegisterFn2 = technical2.AudioCaptureRegisterFn2;
pub const driver_api2_magic = technical2.driver_api2_magic;
pub const driver_api2_version = technical2.driver_api2_version;
pub const protocol_api2_magic = technical2.protocol_api2_magic;
pub const protocol_api2_version = technical2.protocol_api2_version;
pub const audio_backend2_magic = technical2.audio_backend2_magic;
pub const audio_backend2_version = technical2.audio_backend2_version;
